const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v,d=2)=>Number(v).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const percent = (v,d=2)=>num(v*100,d)+'%';
const plain = html=>html.replace(/<[^>]+>/g,'');
const icons={book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z"/><path d="M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1.5"/><rect x="14" y="4" width="6" height="6" rx="1.5"/><rect x="4" y="14" width="6" height="6" rx="1.5"/><rect x="14" y="14" width="6" height="6" rx="1.5"/>',lab:'<path d="M9 3h6M10 3v6L4 19a1.5 1.5 0 0 0 1.5 2h13a1.5 1.5 0 0 0 1.5-2L14 9V3M7 15h10"/>',review:'<path d="M5 4h14v17l-7-4-7 4z"/>',chart:'<path d="M4 4v16h17M8 15v-4M13 15V7M18 15V4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',bulb:'<path d="M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0l-1 3H9z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 17v4h16v-4"/>',leaf:'<path d="M20 4C10 2 3 7 5 14s14 6 15-10ZM5 20 16 9"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'};
const icon = (name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const latestCourse=()=>courses.at(-1);
const KEY=window.platform.storageKey;
let storageOk=true;
let state={version:1,courses:{},bookmarks:[],notes:{},reviews:[],last:latestCourse().id};
function validState(x){return x&&x.version===1&&typeof x.courses==='object'&&x.courses!==null&&!Array.isArray(x.courses)&&Array.isArray(x.bookmarks)&&x.bookmarks.every(v=>typeof v==='string')&&typeof x.notes==='object'&&x.notes!==null&&!Array.isArray(x.notes)&&Object.values(x.notes).every(v=>typeof v==='string')&&Array.isArray(x.reviews)&&x.reviews.every(v=>typeof v==='string')&&Number.isInteger(x.last)&&courses.some(c=>c.id===x.last);}
try {const saved=JSON.parse(localStorage.getItem(KEY));if(validState(saved)) state={...state,...saved};} catch{storageOk=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));window.platform.saveState(state);}catch{storageOk=false;toast('浏览器未允许保存；本次进度仍可使用，请导出备份。');}}
function record(id){let r=state.courses[id];if(!r||!Array.isArray(r.read)||typeof r.answers!=='object'||!r.answers)r=state.courses[id]={read:[],answers:{},submitted:false,score:0,best:0,attempts:0};const c=courses.find(c=>c.id===id);if(c&&r.courseRevision!==c.revision){Object.assign(r,{answers:{},submitted:false,score:0,best:0,attempts:0,lastAnswers:{},courseRevision:c.revision});r.read=r.read.filter(id=>c.sections.some(s=>s.id===id));}return r;}
function progress(c){const r=record(c.id);const read=c.sections.filter(s=>r.read.includes(s.id)).length;const best=Math.min(c.quiz.length,Number(r.best)||0);return {read,best,pct:Math.round((read+best)/(c.sections.length+c.quiz.length)*100),complete:read===c.sections.length&&best===c.quiz.length};}
function totalProgress(){return Math.round(courses.reduce((n,c)=>n+progress(c).pct,0)/courses.length);}
let route, mobileOpen=false, reviewMode='wrong', flashIndex=0, flashOpen=false, catalogFilter='all', catalogQuery='';
const tabs=[['overview','本讲概览'],['concepts','核心概念'],['formulas','公式速查'],['cases','生活案例'],['calculator','互动实验'],['quiz','随堂测试']];
function getRoute(){const p=location.hash.replace(/^#\/?/,'').split('/');if(p[0]==='course'){const c=courses.find(c=>c.id===Number(p[1]))||latestCourse();return {view:'course',course:c,pane:tabs.some(t=>t[0]===p[2])?p[2]:'overview',section:p[3]};}return {view:['catalog','lab','review','progress'].includes(p[0])?p[0]:'course',course:latestCourse(),pane:'overview'};}
function go(path){if(location.hash==='#/'+path) render();else location.hash='/'+path;}
function courseLink(c,pane='overview',section=''){return `#/course/${c.id}/${pane}${section?'/'+section:''}`;}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3200);}
function shell(){const active=route.view;const p=totalProgress();return `
<div class="mobile-scrim ${mobileOpen?'open':''}" data-action="close-menu"></div>
<aside class="sidebar ${mobileOpen?'open':''}" aria-label="学习导航">
  <a class="brand" href="${courseLink(latestCourse())}"><span class="brand-mark">${icon('book')}</span><span><b>戊戌<span class="brand-period">.</span></b><small>金融知识体系</small></span></a>
  <div class="side-label">你的金融学习空间</div>
  <nav class="primary-nav">
    <a href="#/catalog" class="${active==='catalog'?'active':''}">${icon('grid')}课程总览<span class="tiny-count">${courses.length}</span></a>
    <a href="${courseLink(route.course)}" class="${active==='course'?'active':''}">${icon('book')}课程学习</a>
    <a href="#/lab" class="${active==='lab'?'active':''}">${icon('lab')}互动实验室</a>
    <a href="#/review" class="${active==='review'?'active':''}">${icon('review')}复习与错题</a>
    <a href="#/progress" class="${active==='progress'?'active':''}">${icon('chart')}学习进度</a>
    ${window.platform.profile.role==='admin'?'<a href="./admin.html">'+icon('grid')+'管理后台</a>':''}
  </nav>
  <div class="side-label course-label">课程目录<span>${courses.length} 讲</span></div>
  <nav class="course-nav">${courses.map(c=>`<a href="${courseLink(c)}" class="${active==='course'&&route.course.id===c.id?'selected':''}"><span class="lesson-index ${progress(c).complete?'done':''}">${progress(c).complete?icon('check'):String(c.id).padStart(2,'0')}</span><span>${c.title}</span>${c.id===latestCourse().id?'<i>新</i>':''}</a>`).join('')}</nav>
  <div class="side-bottom"><div class="learning-note">${icon('leaf')}<span>让理解，成为你的底气</span></div><div class="side-progress"><span>你的学习进度</span><b>${p}%</b></div><div class="bar"><span style="width:${p}%"></span></div><small>${courses.filter(c=>progress(c).complete).length} / ${courses.length} 讲已完成</small></div>
</aside>
<div class="workspace"><header class="topbar"><div class="top-left"><button class="icon-button mobile-toggle" data-action="menu" aria-label="展开导航">${icon('menu')}</button><span class="breadcrumb">学习空间<span>/</span>${({course:'课程学习',catalog:'课程总览',lab:'互动实验室',review:'复习与错题',progress:'学习进度'})[active]}</span></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')}<span>搜索课程、概念</span><kbd>⌘ K</kbd></button><span class="top-divider"></span><span class="profile-avatar" aria-label="学习者">学</span><span class="learner-label">${esc(window.platform.profile.display_name)}</span><span id="cloud-sync-status" class="sync-status">进度已保存</span><button class="icon-button" data-action="account" aria-label="账号设置">${icon('info')}</button><button class="button secondary compact" data-action="logout">退出</button></div></header>
<main id="main" tabindex="-1">${!storageOk?'<div class="notice">当前浏览器未启用持久保存，请在学习进度页导出备份。</div>':''}${page()}</main>
<footer class="footer"><span>戊戌 · 金融知识体系</span><span>理解原理，再做判断。<span class="footer-dot">·</span> 教学案例均为假设，不构成投资建议。</span></footer></div>
<dialog id="search-dialog" class="search-dialog"><form method="dialog"><div class="dialog-head"><b>搜索你的知识体系</b><button class="icon-button" aria-label="关闭搜索">${icon('close')}</button></div></form><label class="search-field">${icon('search')}<input id="global-search" placeholder="试试：久期、复利、到期收益率" autocomplete="off"></label><div id="search-results" class="search-results"><p class="muted">输入课程、知识点或公式关键词。</p></div></dialog>
<input type="file" id="import-file" accept="application/json,.json" hidden>
`}
function page(){switch(route.view){case 'catalog':return catalogPage();case 'lab':return labPage();case 'review':return reviewPage();case 'progress':return progressPage();default:return coursePage();}}
function chartSvg(face=1000,coupon=.03,years=5,y=.04,m=1,hero=false){const low=Math.min(0,y-.01),high=Math.max(.08,y+.02),samples=Array.from({length:41},(_,i)=>{const rate=low+(high-low)*i/40;return [rate,bondMetrics(face,coupon,years,rate,m).price];});const prices=samples.map(s=>s[1]),max=Math.max(...prices)*1.03,min=Math.min(...prices)*.97;const x=v=>45+(v-low)/(high-low)*370,py=v=>177-(v-min)/(max-min)*132;const d=samples.map(([a,b],i)=>`${i?'L':'M'} ${x(a).toFixed(2)} ${py(b).toFixed(2)}`).join(' ');const price=bondMetrics(face,coupon,years,y,m).price;return `<svg viewBox="0 0 455 225" class="yield-chart ${hero?'hero-chart':''}" role="img" aria-label="普通固定票息债券价格随到期收益率上升而下降；当前收益率${percent(y)}，价格${num(price)}"><defs><linearGradient id="chart-fill-${hero?'hero':'calc'}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hero?'#b8db95':'#2b8266'}" stop-opacity=".24"/><stop offset="1" stop-color="${hero?'#b8db95':'#2b8266'}" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="45" y1="${45+i*44}" x2="415" y2="${45+i*44}" class="grid-line"/>`).join('')}<text x="45" y="24" class="chart-label">债券价格（元）</text><path d="${d} L415 184 L45 184 Z" fill="url(#chart-fill-${hero?'hero':'calc'})"/><path d="${d}" fill="none" stroke="${hero?'#c2e49f':'#278164'}" stroke-width="3"/><line x1="${x(y)}" x2="${x(y)}" y1="${py(price)}" y2="184" class="chart-guide"/><circle cx="${x(y)}" cy="${py(price)}" r="6" fill="${hero?'#c2e49f':'#278164'}" stroke="${hero?'#183f36':'white'}" stroke-width="3"/>${[0,1,2,3,4].map(i=>{const v=low+(high-low)*i/4;return `<text x="${x(v)}" y="204" class="chart-label" text-anchor="middle">${num(v*100,0)}%</text>`}).join('')}<text x="415" y="224" text-anchor="end" class="chart-label">到期收益率</text><text x="${Math.min(380,x(y)+12)}" y="${py(price)-12}" class="chart-value">¥${num(price)}</text></svg>`;}
function coursePage(){const c=route.course,p=progress(c),r=record(c.id);const saved=state.bookmarks.includes(c.id+':all');return `<div class="page-eyebrow">LEARN WITH CLARITY<span>循序渐进 · 学以致用</span></div><div class="page-heading"><div><h1>${route.pane==='overview'?'今天，让金融更好懂。':c.title}</h1><p>${route.pane==='overview'?'把复杂的知识，变成生活中用得上的判断。':`第${chinese(c.id)}讲 · ${c.subtitle}`}</p></div><button class="button secondary compact" data-action="bookmark" data-key="${c.id}:all">${icon('review')}${saved?'已加入复习':'加入复习'}</button></div>
${route.pane==='overview'?`<section class="lesson-hero"><div class="hero-copy"><div class="hero-eyebrow"><span>第${chinese(c.id)}讲</span>${c.category}${c.id===latestCourse().id?'<b>最新课程</b>':''}</div><h2>${c.title}</h2><p>${c.description}</p><div class="hero-meta"><span>${icon('clock')}约 ${c.minutes} 分钟</span><span>${icon('book')}${c.sections.length} 个知识单元</span><span>${icon('target')}${c.quiz.length} 道随堂测试</span></div><a class="button lime" href="${courseLink(c,'concepts',r.read.length?c.sections.find(s=>!r.read.includes(s.id))?.id||c.sections[0].id:'')}">${icon('book')}${p.read?'继续学习':'开始学习'}</a></div>${heroVisual(c)}</section>`:''}
<nav class="lesson-tabs" aria-label="本讲内容">${tabs.map(([key,title])=>`<a href="${courseLink(c,key)}" class="${route.pane===key?'active':''}" ${route.pane===key?'aria-current="page"':''}>${title}${key==='calculator'?'<span class="tab-dot"></span>':''}</a>`).join('')}</nav>
<div class="lesson-pane">${({overview:overview,concepts:concepts,formulas:formulas,cases:cases,calculator:calculator,quiz:quiz})[route.pane](c)}</div>`;}

function heroVisual(c){
  if(c.calculator==='bond')return `<div class="hero-visual"><div class="bond-mini"><span>一张债券，一组未来现金流</span><div><b>¥1,000</b><i>面值</i></div><div class="bond-mini-bottom"><span>年票面利率 <strong>3.0%</strong></span><span>剩余期限 <strong>5 年</strong></span></div></div>${chartSvg(1000,.03,5,.04,1,true)}<span class="visual-caption">收益率在变，价格也在变。</span></div>`;
  const steps=c.calculator==='institution'?[['理解商业模式','客户资产、机构收入与自有资本'],['核对经营质量','费用、成本、损失与资本回报'],['搭建治理体系','投委会、风险边界与长期激励']]:c.calculator==='acquisition'?[['看懂产业逻辑','产业链、控制权与并购动机'],['算清交易价值','独立估值、协同、溢价与融资'],['验证整合成果','现金流、组织协同与退出']]:[['读懂核心概念','把名词放回真实生活'],['亲手调整数字','看清假设如何改变结果'],['练习与复习','把知识变成自己的判断']];
  return `<div class="hero-visual knowledge-visual"><span class="hero-map-label">第${chinese(c.id)}讲 · 理解路径</span><ol class="hero-steps">${steps.map(([title,desc],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><b>${title}</b><small>${desc}</small></div></li>`).join('')}</ol><span class="visual-caption">学一个概念，连接一个判断。</span></div>`;
}
function updateBusiness(kind,d){
  try{
    let stats,note,table='';
    if(kind==='institution'){
      const m=institutionMetrics(d.aum,d.fee/100,d.cost,d.loss,d.tax/100,d.capital);
      stats=[['简化风险调整资本回报 RAROC',percent(m.raroc)],['年度管理费收入',num(m.revenue)+' 万元'],['扣预期损失后税前利润',num(m.pretax)+' 万元'],['风险调整税后利润',num(m.adjustedProfit)+' 万元'],['成本收入比 CIR',m.costIncome===null?'收入为零，不适用':percent(m.costIncome)],['税前盈亏平衡 AUM',m.breakEvenAum===null?'费率为零，无有限解':num(m.breakEvenAum)+' 万元']];
      note='一年期、仅管理费收入的简化模型；AUM 为全年平均收费基数，属于客户管理资产。预期损失是机构自身承担的损失，经济资本是人为给定的风险缓冲；亏损时不确认税收抵扣。此处 RAROC 不是客户收益率，也不是监管资本充足率。';
    }else{
      const m=acquisitionMetrics(d.standalone,d.offer,d.debt,d.cash,d.synergy,d.years,d.rate/100,d.realization/100,d.integration,d.fees);
      stats=[['买方增量净现值 NPV',num(m.npv)+' 万元'],['协同现金流现值',num(m.synergyPV)+' 万元'],['企业价值收购溢价',num(m.premium)+' 万元'],['简化股权对价',num(m.equityPrice)+' 万元'],['盈亏平衡企业报价',num(m.maxOffer)+' 万元']];
      note='NPV '+(m.npv>=0?'非负：在这些假设下，协同覆盖了溢价与费用。':'为负：在这些假设下，协同不足以覆盖溢价与费用。')+' 全部金额单位为万元；每年年末产生等额增量税后自由现金流，期满后为零，无终值。兑现比例只缩减金额，不是完整风险模型；折现率需与风险匹配。整合与交易费用在今天支付。股权对价按 EV－有息债务＋多余现金计算，未计优先股、少数股东权益、营运资本调整或融资费用。';
      table=`<details class="cashflows"><summary>查看协同折现明细</summary><div class="table-scroll"><table><thead><tr><th>年份</th><th>兑现后的现金流（万元）</th><th>现值（万元）</th></tr></thead><tbody>${m.cashflows.map(c=>`<tr><td>${c.year}</td><td>${num(c.cash)}</td><td>${num(c.pv)}</td></tr>`).join('')}</tbody></table></div></details>`;
    }
    $('#simple-result').innerHTML=`<div class="simple-result-inner">${stats.map(([l,v],i)=>i===0?`<div class="result-main"><span>${l}</span><strong>${v}</strong></div>`:resultStat(l,v)).join('')}<p class="model-note">${note}</p>${table}</div>`;
  }catch(e){errorResult($('#simple-result'),e.message);}
}

function chinese(n){const d=['','一','二','三','四','五','六','七','八','九','十'];if(n<=10)return d[n];if(n<20)return '十'+d[n%10];if(n<100)return d[Math.floor(n/10)]+'十'+d[n%10];return String(n);}
function overview(c){const p=progress(c);const groups=c.id===10?[{icon:'file',title:'认识一张债券',desc:'从借款契约到面值、票息与收益率',ids:['nature','face','coupon','ytm','types','convertible'],tag:'基础认知'},{icon:'chart',title:'理解价格的变化',desc:'利率、价格、久期与凸性如何相连',ids:['price','duration','convexity'],tag:'核心原理'},{icon:'target',title:'看清收益背后的风险',desc:'评级、利差、违约与债基净值',ids:['rating','spread','default','fund'],tag:'风险识别'},{icon:'grid',title:'把债券放进投资组合',desc:'让股票与债券服务同一个生活目标',ids:['allocation'],tag:'实际应用'}]:c.sections.map(s=>({icon:'book',title:s.title.split('：')[0],desc:plain(s.body).slice(0,38)+'…',ids:[s.id],tag:'核心知识'}));return `<div class="overview-grid"><div><div class="section-heading"><h2>这一讲，你会学到什么</h2><span class="muted">从理解到应用，走完一条完整路径</span></div><div class="path-grid">${groups.map(g=>`<a class="path-card" href="${courseLink(c,'concepts',g.ids[0])}"><span class="tile-icon">${icon(g.icon)}</span><div><small>${g.tag}</small><h3>${g.title}</h3><p>${g.desc}</p><div class="tag-list">${g.ids.map(id=>`<span>${c.sections.find(s=>s.id===id).title.split('：')[0]}</span>`).join('')}</div></div></a>`).join('')}</div><div class="callout soft"><span class="tile-icon">${icon('bulb')}</span><div><b>先想一个生活里的问题</b><p>${c.id===10?'“债券明明会付利息，为什么买了债券基金还会亏？” 带着这个问题学完本讲，你会有自己的解释。':c.subtitle+' 带着这个问题读概念、试计算，再用测试检验理解。'}</p></div></div></div><aside class="overview-aside"><div class="white-card course-progress"><div class="card-topline"><h3>本讲学习进度</h3><span>${p.pct}%</span></div><div class="bar"><span style="width:${p.pct}%"></span></div><div class="progress-item">${icon('book')}阅读知识单元<b>${p.read}/${c.sections.length}</b></div><div class="progress-item">${icon('target')}测试最佳答对<b>${p.best}/${c.quiz.length}</b></div><p class="small muted">完成全部阅读标记，并在测试中全部答对，即完成本讲。</p></div><div class="white-card lab-promo"><span class="tile-icon">${icon('lab')}</span><h3>理解，来自亲手试一试</h3><p>${c.id===10?'拖动收益率，观察债券价格；调整股债比例，看看组合会怎样。':'改变输入、观察结果，把抽象公式变成自己的直觉。'}</p><a href="${courseLink(c,'calculator')}" class="text-link">打开互动实验</a></div><div class="prereq"><small>知识衔接</small><p>${c.id===10?'利率 · 风险与收益 · 股票与股权':'每一讲，都是下一步理解的起点。'}</p>${courses.indexOf(c)>0?`<a class="text-link" href="${courseLink(courses[courses.indexOf(c)-1])}">温习上一讲</a>`:''}</div></aside></div>`;}
function formulaBox(s){return s.formula?`<div class="formula-box"><span>把概念写成公式</span><code>${esc(s.formula)}</code><p>${esc(s.meaning||'')}</p></div>`:'';}
function concepts(c){const r=record(c.id);return `<div class="reading-layout"><div class="reading-body"><div class="section-heading"><h2>核心概念，逐个读懂</h2><span class="muted">读完后，标记你的理解</span></div>${c.sections.map(s=>`<article class="concept-article" id="concept-${s.id}"><div class="article-top"><span class="eyebrow">${c.category}</span><button class="icon-button ${state.bookmarks.includes(c.id+':'+s.id)?'bookmarked':''}" data-action="bookmark" data-key="${c.id}:${s.id}" aria-label="${state.bookmarks.includes(c.id+':'+s.id)?'取消复习收藏':'加入复习'}">${icon('review')}</button></div><h2>${s.title}</h2><div class="prose">${s.body}</div>${formulaBox(s)}<button class="button ${r.read.includes(s.id)?'understood':'secondary'} compact" data-action="read" data-course="${c.id}" data-section="${s.id}">${icon('check')}${r.read.includes(s.id)?'已理解，点击取消标记':'我已理解这个概念'}</button></article>`).join('')}<div class="reading-next"><div><b>读懂原理后，亲手验证一下。</b><p>把公式里的数字换掉，看看结果如何变化。</p></div><a class="button primary" href="${courseLink(c,'calculator')}">进入互动实验</a></div>${sourceBlock(c)}</div><aside class="reading-toc"><span class="side-label">本讲知识地图</span>${c.sections.map(s=>`<a href="${courseLink(c,'concepts',s.id)}" class="${r.read.includes(s.id)?'read':''}"><span class="toc-check">${r.read.includes(s.id)?icon('check'):''}</span>${s.title.split('：')[0]}</a>`).join('')}</aside></div>`;}
function sourceBlock(c){const refs=sources.filter(s=>(s.courses||[10]).includes(c.id));if(!refs.length)return '';return `<details class="sources"><summary>${icon('file')}学习参考与口径说明</summary><p>课程以通用金融原理为主，监管分类的例子注明地区与历史调整。以下为原始参考资料；案例和计算器采用教学假设。</p>${refs.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer"><b>${s.title}</b><span>${s.org}</span></a>`).join('')}</details>`;}
function formulas(c){const list=c.sections.filter(s=>s.formula);return `<div class="section-heading"><div><h2>公式速查</h2><p class="muted">先看假设，再代入数字；单位和时间口径要一致。</p></div><a class="button secondary compact" href="${courseLink(c,'calculator')}">${icon('lab')}用公式算一算</a></div><div class="formula-grid">${list.map(s=>`<article class="white-card formula-card"><h3>${s.title.split('：')[0]}</h3>${formulaBox(s)}<a class="text-link" href="${courseLink(c,'concepts',s.id)}">回到概念讲解</a></article>`).join('')}</div>${c.id===10?`<div class="callout soft">${icon('info')}<p>收益率变化 1 个百分点要写成 0.01；100bp = 1 个百分点。年化名义收益率与有效年收益率应区分，半年付息时尤其要留意。</p></div>`:''}`;}
function cases(c){return `<div class="section-heading"><div><h2>把知识放进生活</h2><p class="muted">用具体的数字，检验你对概念的理解。</p></div><span class="pill">${c.cases.length} 个教学案例</span></div><div class="case-list">${c.cases.map((k,i)=>`<article class="case-card"><div class="case-mark">${icon(i===1?'chart':'file')}<span>生活案例</span></div><h2>${k.title}</h2><div class="prose">${k.body}</div><div class="case-takeaway">${icon('bulb')}<div><b>带走一个判断</b><p>${k.takeaway}</p></div></div></article>`).join('')}</div><div class="reading-next"><p>换一组数字，结果还一样吗？</p><a class="button primary" href="${courseLink(c,'calculator')}">自己动手验证</a></div>`;}
function field(label,name,value,min,max,step=1,suffix='',type='number'){return `<label class="input-field"><span>${label}</span><div class="input-wrap"><input type="${type}" name="${name}" value="${value}" ${min!==null?`min="${min}"`:''} ${max!==null?`max="${max}"`:''} step="${['years','shares'].includes(name)?1:'any'}" required aria-label="${label}">${suffix?`<span>${suffix}</span>`:''}</div></label>`;}
function calculator(c){return `<div class="section-heading"><div><h2>让公式动起来</h2><p class="muted">每一次调整，都是一个新的“如果”。</p></div><span class="pill green">即时计算</span></div>${c.calculator==='bond'?bondCalculator()+portfolioCalculator():c.calculator==='portfolio'?portfolioCalculator():simpleCalculator(c)}<div class="callout soft calculator-note">${icon('info')}<p>计算结果基于所填假设，用于理解原理。未计税费、违约、交易成本及真实市场的复杂条款，不代表实际收益。</p></div>`;}
function bondCalculator(){return `<section class="calculator-card" id="bond-lab"><div class="calc-card-head"><span class="tile-icon">${icon('lab')}</span><div><h3>债券价格与收益率实验室</h3><p>看见利率变化背后的每一笔现金流。</p></div><span class="calc-badge">BOND LAB</span></div><form id="bond-form" class="calc-layout"><div class="calc-inputs"><div class="segmented"><label><input type="radio" name="mode" value="price" checked><span>计算债券价格</span></label><label><input type="radio" name="mode" value="yield"><span>反推到期收益率</span></label></div><div class="field-grid">${field('债券面值','face',1000,1,100000000,1,'元')}${field('年票面利率','coupon',3,0,50,.1,'%')}${field('剩余期限','years',5,1,50,1,'年')}<label class="input-field"><span>付息频率</span><div class="select-wrap"><select name="frequency" aria-label="付息频率"><option value="1">每年一次</option><option value="2">每半年一次</option></select></div></label></div><div id="yield-input">${field('年化名义到期收益率','ytm',4,-20,50,.1,'%')}<input class="range-input" type="range" min="0" max="10" value="4" step=".1" name="yieldSlider" aria-label="拖动到期收益率"><div class="range-labels"><span>0%</span><span>拖动观察价格变化</span><span>10%</span></div></div><div id="price-input" hidden>${field('当前成交价格','market',955.48,.01,100000000,.01,'元')}</div><div class="calc-assumptions"><b>实验假设</b><p>普通固定票息、到期一次还本；在付息日刚付息后估值。年限为整数，未计应计利息与嵌入期权。</p></div></div><div class="calc-output" id="bond-result" aria-live="polite"></div></form><div class="shock-section"><div><h4>再试一次：收益率突然变化</h4><p>比较久期、凸性近似与重新定价的差别。</p></div><label>收益率变化 <select id="shock" aria-label="收益率变化"><option value=".01">上升 100bp</option><option value="-.01">下降 100bp</option><option value=".02">上升 200bp</option><option value="-.02">下降 200bp</option><option value=".005">上升 50bp</option></select></label><div id="shock-result" class="shock-results" aria-live="polite"></div></div><details class="cashflows"><summary>查看每期现金流与折现明细</summary><div id="cashflow-result" class="table-scroll"></div></details></section>`;}
function portfolioCalculator(){return `<section class="calculator-card" id="portfolio-lab"><div class="calc-card-head"><span class="tile-icon blue">${icon('grid')}</span><div><h3>股票与债券组合实验</h3><p>收益可以加权，风险还要看相关性。</p></div><span class="calc-badge">PORTFOLIO LAB</span></div><form id="portfolio-form" class="calc-layout"><div class="calc-inputs"><label class="input-field"><span>股票比例 <b id="weight-label">60%</b></span><input type="range" name="weight" min="0" max="100" step="1" value="60" aria-label="股票比例"><div class="range-labels"><span>0% 股票</span><span>100% 股票</span></div></label>${field('组合本金','principal',100000,1,100000000,1000,'元')}<div class="field-grid">${field('股票假设年收益','stockReturn',8,-100,100,.5,'%')}${field('债券假设年收益','bondReturn',3,-100,100,.5,'%')}${field('股票年波动率','stockVol',20,0,100,.5,'%')}${field('债券年波动率','bondVol',5,0,100,.5,'%')}</div>${field('股债收益相关系数','correlation',.1,-1,1,.1)}<div class="scenario-buttons"><span>教学情景</span><button type="button" data-scenario="growth">温和增长</button><button type="button" data-scenario="drawdown">股市回撤</button><button type="button" data-scenario="inflation">股债同跌</button></div></div><div class="calc-output" id="portfolio-result" aria-live="polite"></div></form><p class="model-note">波动率结果是给定假设的两资产模型标准差，不是最大可能亏损。情景按钮设置收益与波动的教学假设，不代表市场预测；相关性可能随环境变化。</p></section>`;}
function simpleCalculator(c){const config={purchasing:['购买力计算器','同样的金额，未来还能买多少？',[['当前金额','amount',10000,0,1e9,100,'元'],['假设年均通胀','rate',3,-20,50,.1,'%'],['经过时间','years',5,0,100,1,'年']]],credit:['等额本息计算器','看清月供和总利息。',[['借款本金','amount',10000,1,1e9,100,'元'],['名义年利率','rate',6,0,50,.1,'%'],['借款年数','years',1,1,40,1,'年']]],compound:['复利与单利计算器','让时间和利率一起工作。',[['起始本金','amount',10000,0,1e9,100,'元'],['假设年收益率','rate',5,-90,100,.1,'%'],['投资年数','years',10,0,100,1,'年']]],fx:['换汇预算计算器','比较两种汇率下的本币支出。',[['外币金额','amount',20000,0,1e9,100,'英镑'],['原汇率','rate',9,.01,1000,.01,'元/英镑'],['比较汇率','newRate',9.5,.01,1000,.01,'元/英镑']]],inflation:['名义与实际收益计算器','钱变多，与购买力增加之间还有一步。',[['起始本金','amount',10000,0,1e9,100,'元'],['名义年收益率','rate',4,-90,100,.1,'%'],['假设年均通胀','inflation',3,-20,50,.1,'%'],['经过年数','years',5,0,100,1,'年']]],balance:['家庭资产负债计算器','用一张快照看清属于你的部分。',[['现金与存款','cash',100000,0,1e10,1000,'元'],['证券资产','securities',200000,0,1e10,1000,'元'],['房产等其他资产','property',1000000,0,1e10,1000,'元'],['全部负债','debt',800000,0,1e10,1000,'元'],['每月现金流入','income',20000,0,1e8,100,'元'],['每月全部现金流出','outflow',15000,0,1e8,100,'元']]],liquidity:['现金缓冲压力测试','假设收入中断，能支撑多久？',[['可即时动用的现金','amount',60000,0,1e9,1000,'元'],['每月必要现金支出','expense',12000,1,1e8,100,'元'],['近期必须一次付出的款项','due',0,0,1e9,100,'元']]],valuation:['股票估值计算器','从股价、盈利与净资产看估值倍数。',[['每股价格','price',60,.01,1e6,.1,'元'],['每股收益 EPS','eps',3,-1e5,1e5,.1,'元'],['每股净资产','book',10,-1e5,1e5,.1,'元'],['股份数量','shares',1000000,1,1e12,1,'股']]],institution:['机构经营与风险资本实验','管理规模不等于自有资本，收入也不等于利润。',[['平均收费管理规模 AUM','aum',100000,0,1e10,1000,'万元'],['年管理费率','fee',1,0,10,.1,'%'],['年度经营成本','cost',600,0,1e8,10,'万元'],['机构承担的年度预期损失','loss',100,0,1e8,10,'万元'],['简化所得税率','tax',25,0,100,1,'%'],['配置的经济资本','capital',2000,.01,1e9,100,'万元']]],acquisition:['并购估值与协同实验','能创造价值，不代表任何成交价都值得付。',[['目标独立企业价值 EV','standalone',10000,0,1e10,100,'万元'],['拟支付企业价值 EV','offer',11500,0,1e10,100,'万元'],['承接的有息债务','debt',2000,0,1e10,100,'万元'],['可抵扣的多余现金','cash',500,0,1e10,100,'万元'],['年度增量税后自由现金流','synergy',600,-1e8,1e8,10,'万元'],['协同持续年数','years',5,1,50,1,'年'],['协同现金流折现率','rate',8,0,100,.5,'%'],['协同兑现比例','realization',100,0,100,5,'%'],['立即支付的整合成本','integration',500,0,1e8,10,'万元'],['立即支付的交易费用','fees',200,0,1e8,10,'万元']]]}[c.calculator];return `<section class="calculator-card"><div class="calc-card-head"><span class="tile-icon">${icon('lab')}</span><div><h3>${config[0]}</h3><p>${config[1]}</p></div></div><form id="simple-form" data-kind="${c.calculator}" class="calc-layout"><div class="calc-inputs field-grid">${config[2].map(f=>field(...f)).join('')}</div><div id="simple-result" class="calc-output" aria-live="polite"></div></form></section>`;}
function data(form){return Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,k==='mode'?v:Number(v)]));}
function invalid(form){return [...form.elements].filter(el=>el.type!=='submit'&&!el.disabled&&!el.closest('[hidden]')).some(el=>el.willValidate&&!el.checkValidity());}
function errorResult(target,msg='请填写范围内的有效数字。'){target.innerHTML=`<div class="calc-error" role="alert">${icon('info')}<p>${esc(msg)}</p></div>`;}
function resultStat(label,value,note=''){return `<div class="result-stat"><span>${label}</span><b>${value}</b>${note?`<p>${note}</p>`:''}</div>`;}
function updateBond(){const f=$('#bond-form');if(!f)return;const isPrice=f.elements.mode.value==='price';$('#yield-input').hidden=!isPrice;$('#price-input').hidden=isPrice;f.elements.ytm.disabled=!isPrice;f.elements.yieldSlider.disabled=!isPrice;f.elements.market.disabled=isPrice;const d=data(f);if(invalid(f)){errorResult($('#bond-result'));$('#shock-result').innerHTML='';$('#cashflow-result').innerHTML='';return;}try{const face=d.face,c=d.coupon/100,m=d.frequency,y=isPrice?d.ytm/100:yieldToMaturity(face,c,d.years,d.market,m);const b=bondMetrics(face,c,d.years,y,m);$('#bond-result').innerHTML=`<div class="result-main"><span>${isPrice?'理论债券全价':'反推年化名义到期收益率'}</span><strong>${isPrice?'¥'+num(b.price):percent(y,3)}</strong><small>${isPrice?(b.price<face?'折价交易':b.price>face?'溢价交易':'平价交易'):'有效年收益率 '+percent((1+y/m)**m-1,3)}</small></div>${chartSvg(face,c,d.years,y,m)}<div class="result-mini-grid">${resultStat('每年票息','¥'+num(face*c))}${resultStat('修正久期',num(b.modified,3)+' 年')}${resultStat('麦考利久期',num(b.macaulay,3)+' 年')}${resultStat('凸性',num(b.convexity,3)+' 年²')}</div>`;const shock=Number($('#shock').value),newY=y+shock;if(newY/m<=-1)throw new Error('变化后的收益率超出模型范围。');const actual=bondMetrics(face,c,d.years,newY,m).price/b.price-1,linear=-b.modified*shock,conv=linear+.5*b.convexity*shock**2;$('#shock-result').innerHTML=`${resultStat('久期一阶近似',percent(linear))}${resultStat('加入凸性近似',percent(conv))}${resultStat('现金流重新定价',percent(actual))}<p class="small muted">变化后 YTM：${percent(newY)}。收益率变化较大时，近似与精确重新定价可能出现明显差异。</p>`;$('#cashflow-result').innerHTML=`<table><thead><tr><th>第几次付息</th><th>距今（年）</th><th>合同现金流</th><th>当前折现值</th></tr></thead><tbody>${b.cashflows.map(cf=>`<tr><td>${cf.period}</td><td>${num(cf.year,1)}</td><td>¥${num(cf.cash)}</td><td>¥${num(cf.pv)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="3">现值合计</th><th>¥${num(b.price)}</th></tr></tfoot></table>`;}catch(e){errorResult($('#bond-result'),e.message);}}
function updatePortfolio(){const f=$('#portfolio-form');if(!f)return;if(invalid(f)){errorResult($('#portfolio-result'));return;}const d=data(f),w=d.weight/100;$('#weight-label').textContent=d.weight+'%';try{const m=portfolioMetrics(w,d.stockReturn/100,d.bondReturn/100,d.stockVol/100,d.bondVol/100,d.correlation);$('#portfolio-result').innerHTML=`<div class="allocation-donut" style="--stock:${d.weight}%"><div><b>${d.weight}<small>%</small></b><span>股票占比</span></div></div><div class="allocation-legend"><span><i></i>股票 ${d.weight}%</span><span><i></i>债券 ${100-d.weight}%</span></div><div class="result-mini-grid">${resultStat('模型年收益',percent(m.expected))}${resultStat('模型年波动率',percent(m.volatility))}${resultStat('假设一年后金额','¥'+num(d.principal*(1+m.expected)))}${resultStat('假设收益金额','¥'+num(d.principal*m.expected))}</div><p class="model-note">收益按一年单期、无期间再平衡计算。金额均为情景演示，没有计入风险分布、税费和实际成交影响。</p>`;}catch(e){errorResult($('#portfolio-result'),e.message);}}
function updateSimple(){const f=$('#simple-form');if(!f)return;if(invalid(f)){errorResult($('#simple-result'));return;}const d=data(f),kind=f.dataset.kind;let stats=[],note='';if(kind==='compound'){const end=compound(d.amount,d.rate/100,d.years),simple=d.amount*(1+d.rate/100*d.years);stats=[['复利终值','¥'+num(end)],['单利终值','¥'+num(simple)],['复利与单利差额','¥'+num(end-simple)]];note='假设每年收益率固定，利息按同样利率再投资；单利与复利都可能受到亏损影响。';}if(kind==='purchasing'){stats=[['以今天物价衡量的购买力','¥'+num(d.amount/(1+d.rate/100)**d.years)],['维持同等购买力需有金额','¥'+num(d.amount*(1+d.rate/100)**d.years)]];note='假设金额不计利息、每年通胀率恒定。';}if(kind==='credit'){const i=d.rate/1200,n=d.years*12,payment=i===0?d.amount/n:d.amount*i/(1-(1+i)**(-n));stats=[['每月还款','¥'+num(payment)],['总利息','¥'+num(payment*n-d.amount)],['本息总还款','¥'+num(payment*n)]];note='固定名义年利率除以 12，按月等额本息；无额外费用，月供四舍五入可能产生尾期差额。';}if(kind==='fx'){const old=d.amount*d.rate,now=d.amount*d.newRate;stats=[['比较汇率下的成本','¥'+num(now)],['原汇率下的成本','¥'+num(old)],['人民币成本变化',percent(now/old-1)]];if(d.amount===0)stats[2][1]='金额为零，比例不适用';note='教学汇率，以人民币/英镑报价，未计换汇点差与费用。';}if(kind==='inflation'){const nominal=compound(d.amount,d.rate/100,d.years),real=nominal/(1+d.inflation/100)**d.years;stats=[['名义期末金额','¥'+num(nominal)],['按今天物价的实际金额','¥'+num(real)],['实际年收益率',percent((1+d.rate/100)/(1+d.inflation/100)-1)]];note='假设收益率与通胀率每年固定，收益每年复投。';}if(kind==='balance'){const assets=d.cash+d.securities+d.property;stats=[['家庭净资产','¥'+num(assets-d.debt)],['总资产','¥'+num(assets)],['资产负债率',assets?percent(d.debt/assets):'总资产为零，不适用'],['月净现金流','¥'+num(d.income-d.outflow)]];note='全部用同币种计价；月流出应包含实际还本付息。估值不是可立即兑现的金额。';}if(kind==='liquidity'){const available=Math.max(0,d.amount-d.due);stats=[['可支撑的月数',num(available/d.expense,1)+' 个月'],['扣除近期付款后现金','¥'+num(available)]];note=d.due>d.amount?'近期必须付款已超过现金，短缺 ¥'+num(d.due-d.amount)+'。':'假设后续收入为零、每月必要支出固定；未到期或需折价出售的资产不计入。';}if(kind==='valuation'){stats=[['市盈率 PE',d.eps>0?num(d.price/d.eps)+' 倍':'EPS 非正，通常不适用'],['市净率 PB',d.book>0?num(d.price/d.book)+' 倍':'净资产非正，通常不适用'],['简化总市值','¥'+num(d.price*d.shares,0)]];note='简化为单一股价与对应股份数量；EPS、净资产与股数需要匹配口径和报告期。';}if(['institution','acquisition'].includes(kind)){updateBusiness(kind,d);return;}$('#simple-result').innerHTML=`<div class="simple-result-inner">${stats.map(([l,v],i)=>i===0?`<div class="result-main"><span>${l}</span><strong>${v}</strong></div>`:resultStat(l,v)).join('')}<p class="model-note">${note}</p></div>`;}
function quiz(c){const r=record(c.id),answered=c.quiz.filter(q=>Number.isInteger(r.answers[q.id])).length;return `<div class="section-heading"><div><h2>用问题检验理解</h2><p class="muted">答错也有收获，每道题都有解析和对应知识点。</p></div><span class="pill">${answered}/${c.quiz.length} 已作答</span></div>${r.submitted?`<div class="quiz-summary"><span class="tile-icon">${icon('target')}</span><div><b>本次答对 ${r.score} / ${c.quiz.length} 题</b><p>${r.score===c.quiz.length?'全部答对！你已掌握本讲测试要点。':'把薄弱的知识点再看一次，你正在接近理解。'} 最佳成绩 ${r.best}/${c.quiz.length}。</p></div><button class="button secondary compact" data-action="retry" data-course="${c.id}">重新练习</button></div>`:''}<form id="quiz-form" data-course="${c.id}">${c.quiz.map((q,i)=>`<fieldset class="question-card"><legend><span>${String(i+1).padStart(2,'0')}</span>${q.q}</legend><div class="question-options">${q.options.map((o,j)=>`<label class="quiz-option ${r.submitted?(j===q.correct?'correct':j===r.answers[q.id]?'incorrect':''):''}"><input type="radio" name="${q.id}" value="${j}" ${r.answers[q.id]===j?'checked':''} ${r.submitted?'disabled':''}><span class="option-letter">${'ABC'[j]}</span><span>${o}</span>${r.submitted&&j===q.correct?icon('check'):''}</label>`).join('')}</div>${r.submitted?`<div class="answer-explanation ${r.answers[q.id]===q.correct?'right':'wrong'}"><b>${r.answers[q.id]===q.correct?'理解正确':'再看一下这个知识点'}</b><p>${q.explain}</p><a class="text-link" href="${courseLink(c,'concepts',q.section)}">回到对应讲解</a></div>`:''}</fieldset>`).join('')}<div class="quiz-actions">${r.submitted?`<a class="button primary" href="#/review">查看复习与错题</a>`:`<button class="button primary" type="submit">提交并查看解析</button><span class="muted small">请完成全部 ${c.quiz.length} 题后提交。已选答案会自动保存。</span>`}</div></form>`;}
function pendingCourseRanges(){const present=new Set(courses.map(c=>c.id)),ranges=[];let start=null;for(let id=1;id<=latestCourse().id+1;id++){if(id<=latestCourse().id&&!present.has(id)){start??=id;}else if(start!==null){ranges.push(start===id-1?String(start):start+'–'+(id-1));start=null;}}return ranges.join('、');}
function catalogPage(){const list=courses.filter(c=>(catalogFilter==='all'||(catalogFilter==='unfinished'?!progress(c).complete:progress(c).complete))&&(`${c.title}${c.subtitle}${c.keywords.join('')}`.includes(catalogQuery)));return `<div class="page-eyebrow">YOUR KNOWLEDGE MAP<span>从基础认知，走向独立判断</span></div><div class="page-heading"><div><h1>建立自己的金融知识体系</h1><p>${chinese(courses.length)}讲已发布课程，连接日常生活中的每一个金融问题。</p></div></div><div class="catalog-stats"><div>${icon('book')}<b>${courses.length}</b><span>系统课程</span></div><div>${icon('lab')}<b>${courses.length+1}</b><span>互动实验</span></div><div>${icon('target')}<b>${courses.reduce((n,c)=>n+c.quiz.length,0)}</b><span>练习问题</span></div><div>${icon('leaf')}<b>持续</b><span>更新与复习</span></div></div><div class="catalog-toolbar"><div class="filter-tabs">${[['all','全部课程'],['unfinished','待学习'],['complete','已完成']].map(([v,l])=>`<button class="${catalogFilter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><label class="inline-search">${icon('search')}<input id="catalog-search" aria-label="搜索课程" placeholder="搜索课程关键词" value="${esc(catalogQuery)}"></label></div><div class="catalog-list" id="catalog-list">${catalogCards(list)}</div><section class="future-card">${icon('leaf')}<div><h3>知识体系，继续生长</h3><p>${pendingCourseRanges()?'第'+pendingCourseRanges()+'讲待同步。已发布课程按原讲次显示。':''}课程与复习内容持续更新，沿着目录继续学习新的专题。</p></div><span class="pill">后续更新</span></section>`;}
function catalogCards(list){return list.length?list.map(c=>{const p=progress(c);return `<a class="catalog-card" href="${courseLink(c)}"><div class="catalog-number">${String(c.id).padStart(2,'0')}</div><div class="catalog-copy"><span class="eyebrow">${c.category}</span><h2>${c.title}${c.id===latestCourse().id?'<span class="new-label">最新课程</span>':''}</h2><p>${c.subtitle}</p><div class="catalog-tags">${c.keywords.map(k=>`<span>${k}</span>`).join('')}</div></div><div class="catalog-meta"><span>${icon('clock')}约 ${c.minutes} 分钟</span><div class="bar"><span style="width:${p.pct}%"></span></div><small>${p.complete?'已完成':p.pct?'学习中 '+p.pct+'%':'尚未开始'}</small></div><span class="open-course">进入课程</span></a>`}).join(''):'<div class="empty-state">没有符合条件的课程，试试其他关键词或筛选。</div>';}
function labPage(){return `<div class="page-eyebrow">LEARNING BY DOING<span>把抽象公式，变成直觉</span></div><div class="page-heading"><div><h1>互动实验室</h1><p>从一个“如果”出发，观察结果，理解原因。</p></div></div><div class="lab-grid">${courses.map(c=>`<a class="lab-card white-card" href="${courseLink(c,'calculator')}"><span class="tile-icon ${c.id%2?'blue':''}">${icon('lab')}</span><span class="eyebrow">第${chinese(c.id)}讲</span><h2>${({purchasing:'购买力',credit:'借贷月供',compound:'单利与复利',fx:'换汇预算',inflation:'名义与实际收益',balance:'家庭资产负债',liquidity:'现金缓冲',portfolio:'风险与组合',valuation:'股票估值',bond:'债券价格与收益率',institution:'机构经营与资本',acquisition:'并购与协同'})[c.calculator]}实验</h2><p>${c.keywords.join(' · ')}</p><span class="text-link">开始实验</span></a>`).join('')}<a class="lab-card white-card featured-lab" href="${courseLink(courses.find(c=>c.calculator==='bond'||c.calculator==='portfolio')||latestCourse(),'calculator')}"><span class="tile-icon">${icon('grid')}</span><span class="eyebrow">跨课程应用</span><h2>股债配置实验</h2><p>调整权重、情景与相关系数</p><span class="text-link">观察组合变化</span></a></div>`;}
function wrongQuestions(){return courses.flatMap(c=>{const r=record(c.id);const answers=r.lastAnswers||(r.submitted?r.answers:null);return answers?c.quiz.filter(q=>answers[q.id]!==q.correct).map(q=>({c,q,answer:answers[q.id]})):[]});}
function reviewPage(){const wrong=wrongQuestions();return `<div class="page-eyebrow">MAKE KNOWLEDGE STICK<span>复习，是理解的另一半</span></div><div class="page-heading"><div><h1>把学过的，变成自己的</h1><p>从错题返回概念，用卡片练习回忆，也为自己留一段笔记。</p></div></div><nav class="filter-tabs review-tabs">${[['wrong','错题本',wrong.length],['saved','我的收藏',state.bookmarks.length],['flash','复习卡片',courses.reduce((n,c)=>n+c.sections.length,0)],['notes','学习笔记','']].map(([key,label,count])=>`<button data-review="${key}" class="${reviewMode===key?'active':''}">${label}${count!==''?`<span>${count}</span>`:''}</button>`).join('')}</nav>${reviewMode==='wrong'?wrong.length?`<div class="section-heading"><h2>再给这些知识点一次机会</h2><span class="muted">重新完成对应测试后，错题会更新</span></div>${wrong.map(({c,q,answer})=>`<article class="white-card wrong-card"><span class="eyebrow">第${chinese(c.id)}讲 · ${c.title}</span><h3>${q.q}</h3><p><span class="wrong-label">上次选择</span> ${q.options[answer]||'未选择'}</p><details><summary>查看正确答案与解析</summary><p><b>正确答案：${q.options[q.correct]}</b></p><p>${q.explain}</p></details><div class="button-row"><a class="text-link" href="${courseLink(c,'concepts',q.section)}">温习概念</a><a class="button secondary compact" href="${courseLink(c,'quiz')}">回到本讲测试</a></div></article>`).join('')}`:empty('还没有错题','完成一次随堂测试，错题会自动收集在这里。',courseLink(latestCourse(),'quiz'),'去做最新课程测试'):reviewMode==='saved'?savedReview():reviewMode==='flash'?flashReview():notesReview()}`;}
function empty(title,desc,link,label){return `<div class="empty-state"><span class="empty-icon">${icon('book')}</span><h2>${title}</h2><p>${desc}</p>${link?`<a class="button primary" href="${link}">${label}</a>`:''}</div>`;}
function savedReview(){const items=state.bookmarks.map(key=>{const [id,sid]=key.split(':'),c=courses.find(c=>c.id===+id);if(!c)return '';const s=c.sections.find(s=>s.id===sid);if(sid!=='all'&&!s)return '';return `<article class="white-card saved-card"><span class="tile-icon">${icon('review')}</span><div><span class="eyebrow">第${chinese(c.id)}讲 · ${c.title}</span><h3>${s?s.title:'整讲复习 · '+c.title}</h3>${s?`<p>${plain(s.body).slice(0,80)}…</p>`:''}<a class="text-link" href="${courseLink(c,s?'concepts':'overview',s?.id)}">打开学习内容</a></div><button class="icon-button bookmarked" data-action="bookmark" data-key="${esc(key)}" aria-label="移除复习收藏">${icon('review')}</button></article>`;}).join('');return items||empty('把想再读的，放在这里','点击课程或概念旁的书签图标，建立你自己的复习清单。',courseLink(latestCourse()),'浏览最新课程');}
function flashReview(){const cards=courses.flatMap(c=>c.sections.map(s=>({c,s}))),card=cards[flashIndex%cards.length],key=card.c.id+':'+card.s.id;return `<div class="flash-header"><span>知识卡片 ${flashIndex%cards.length+1} / ${cards.length}</span><span>已复习 ${state.reviews.length} 张</span></div><article class="flash-card"><span class="pill">第${chinese(card.c.id)}讲 · ${card.c.title}</span><span class="flash-icon">${icon('bulb')}</span><h2>能用自己的话解释<br>「${card.s.title.split('：')[0]}」吗？</h2><p class="muted">先尝试回忆，再翻开答案。</p>${flashOpen?`<div class="flash-answer prose">${card.s.body}${formulaBox(card.s)}<a class="text-link" href="${courseLink(card.c,'concepts',card.s.id)}">阅读完整讲解</a></div><button class="button primary" data-action="flash-known" data-key="${key}">${icon('check')}已复习，下一张</button>`:`<button class="button primary" data-action="flash-reveal">翻开知识卡片</button>`}</article><div class="flash-controls"><button class="button secondary compact" data-action="flash-prev">上一张</button><button class="button secondary compact" data-action="flash-next">下一张</button></div>`;}
function notesReview(){return `<div class="notes-layout"><div><h2>用自己的话，写下理解</h2><p class="muted">一个新发现、一个还没想通的问题，都值得留下。</p><label class="input-field"><span>选择课程</span><div class="select-wrap"><select id="note-course">${courses.map(c=>`<option value="${c.id}" ${c.id===Number(state.last)?'selected':''}>第${chinese(c.id)}讲 · ${c.title}</option>`).join('')}</select></div></label><label class="input-field"><span>我的学习笔记</span><textarea id="note-text" rows="12" placeholder="今天我终于明白了……">${esc(state.notes[state.last]||'')}</textarea></label><p class="small muted" id="note-status">输入后会自动保存到你的账号。</p></div><aside class="white-card"><span class="tile-icon">${icon('file')}</span><h3>给理解留一个位置</h3><p>试着回答三个问题：</p><ul><li>这个概念用一句话怎么解释？</li><li>它和之前哪一讲有关？</li><li>我能想出什么生活案例？</li></ul></aside></div>`;}
function progressPage(){const p=totalProgress(),completed=courses.filter(c=>progress(c).complete).length,attempts=courses.reduce((n,c)=>n+record(c.id).attempts,0),read=courses.reduce((n,c)=>n+progress(c).read,0);return `<div class="page-eyebrow">YOUR LEARNING JOURNEY<span>每一点理解，都算数</span></div><div class="page-heading"><div><h1>看见自己的积累</h1><p>进度来自你的阅读标记与测试成绩，随时可以继续。</p></div><div class="button-row"><button class="button secondary compact" data-action="export">${icon('download')}导出备份</button><button class="button secondary compact" data-action="import">${icon('upload')}导入备份</button></div></div><div class="progress-overview"><div class="progress-ring" style="--progress:${p}%"><div><b>${p}<small>%</small></b><span>总体学习进度</span></div></div><div class="progress-metrics">${resultStat('已完成课程',completed+' / '+courses.length)}${resultStat('已理解知识单元',read+' 个')}${resultStat('已提交测试',attempts+' 次')}${resultStat('待温习错题',wrongQuestions().length+' 道')}</div></div><div class="section-heading"><h2>你的课程足迹</h2><span class="muted">阅读完成 + 测试全对 = 本讲完成</span></div><div class="table-scroll white-card progress-table"><table><thead><tr><th>课程</th><th>阅读标记</th><th>最佳答对</th><th>学习进度</th><th></th></tr></thead><tbody>${courses.map(c=>{const p=progress(c);return `<tr><td><b>第${chinese(c.id)}讲</b><span>${c.title}</span></td><td>${p.read}/${c.sections.length}</td><td>${p.best}/${c.quiz.length}</td><td><div class="progress-table-bar"><div class="bar"><span style="width:${p.pct}%"></span></div><span>${p.pct}%</span></div></td><td><a class="text-link" href="${courseLink(c)}">${p.complete?'复习课程':'继续学习'}</a></td></tr>`}).join('')}</tbody></table></div><div class="callout soft">${icon('info')}<p>进度、收藏、答题记录和笔记保存在你的账号中，授权浏览器之间会同步。导出备份可另外保留一份副本；导入的历史测试需重新提交以更新服务器成绩。</p></div>`;}
function render(){route=getRoute();if(route.view==='course'){state.last=route.course.id;save();}$('#app').innerHTML=shell();document.title=(route.view==='course'?route.course.title:({catalog:'课程总览',lab:'互动实验室',review:'复习与错题',progress:'学习进度'})[route.view])+' · 戊戌';updateBond();updatePortfolio();updateSimple();const selected=$('.course-nav .selected');if(selected)selected.scrollIntoView({block:'nearest'});if(route.section)requestAnimationFrame(()=>$('#concept-'+route.section)?.scrollIntoView({behavior:'instant',block:'start'}));}
window.addEventListener('hashchange',()=>{mobileOpen=false;render();if(!route.section)window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();return;}const target=e.target.closest('[data-action]');if(target){const a=target.dataset.action;if(a==='logout'){window.platform.logout();return;}if(a==='account'){showAccount();return;}if(a==='menu'){mobileOpen=true;$('.sidebar').classList.add('open');$('.mobile-scrim').classList.add('open');}if(a==='close-menu'){mobileOpen=false;$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('open');}if(a==='search-result')$('#search-dialog').close();if(a==='search'){$('#search-dialog').showModal();$('#global-search').focus();}if(a==='bookmark'){const key=target.dataset.key;state.bookmarks=state.bookmarks.includes(key)?state.bookmarks.filter(v=>v!==key):[...state.bookmarks,key];save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);toast(state.bookmarks.includes(key)?'已加入复习清单':'已移除复习收藏');}if(a==='read'){const r=record(+target.dataset.course),id=target.dataset.section;r.read=r.read.includes(id)?r.read.filter(v=>v!==id):[...r.read,id];save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);}if(a==='retry'){const r=record(+target.dataset.course);r.answers={};r.submitted=false;save();render();toast('新一轮练习已开始，最佳成绩保留。');}if(a==='flash-reveal'){flashOpen=true;render();}if(['flash-prev','flash-next','flash-known'].includes(a)){if(a==='flash-known'&&!state.reviews.includes(target.dataset.key)){state.reviews.push(target.dataset.key);save();}const count=courses.reduce((n,c)=>n+c.sections.length,0);flashIndex=(flashIndex+(a==='flash-prev'?-1:1)+count)%count;flashOpen=false;render();}if(a==='export'){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='wuxu-learning-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学习备份已导出。');}if(a==='import')$('#import-file').click();}
  const filter=e.target.closest('[data-filter]');if(filter){catalogFilter=filter.dataset.filter;render();}
  const review=e.target.closest('[data-review]');if(review){reviewMode=review.dataset.review;render();}
  const scenario=e.target.closest('[data-scenario]');if(scenario){const f=$('#portfolio-form'),values={growth:[8,3,20,5,.1],drawdown:[-20,4,25,6,-.2],inflation:[-20,-8,25,10,.6]}[scenario.dataset.scenario];['stockReturn','bondReturn','stockVol','bondVol','correlation'].forEach((key,i)=>f.elements[key].value=values[i]);updatePortfolio();}
});
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#bond-form')){if(t.name==='yieldSlider')t.form.elements.ytm.value=t.value;if(t.name==='ytm')t.form.elements.yieldSlider.value=t.value;updateBond();}if(t.closest('#portfolio-form'))updatePortfolio();if(t.closest('#simple-form'))updateSimple();if(t.closest('#quiz-form')){const f=t.form,r=record(+f.dataset.course);r.answers[t.name]=Number(t.value);save();const pill=$('.lesson-pane>.section-heading .pill');if(pill)pill.textContent=Object.keys(r.answers).length+'/'+route.course.quiz.length+' 已作答';}if(t.id==='note-text'){state.notes[$('#note-course').value]=t.value;save();$('#note-status').textContent='正在保存到账号。';}if(t.id==='catalog-search'){catalogQuery=t.value;const list=courses.filter(c=>(catalogFilter==='all'||(catalogFilter==='unfinished'?!progress(c).complete:progress(c).complete))&&(`${c.title}${c.subtitle}${c.keywords.join('')}`.includes(catalogQuery)));$('#catalog-list').innerHTML=catalogCards(list);}if(t.id==='global-search'){const query=t.value.trim().toLowerCase();if(!query){$('#search-results').innerHTML='<p class="muted">输入课程、知识点或公式关键词。</p>';return;}const results=courses.flatMap(c=>{const found=[];if((c.title+c.subtitle).toLowerCase().includes(query))found.push({c,title:c.title,desc:c.subtitle,link:courseLink(c)});c.sections.forEach(s=>{if((s.title+s.body+(s.formula||'')).toLowerCase().includes(query))found.push({c,title:s.title,desc:plain(s.body).slice(0,60)+'…',link:courseLink(c,'concepts',s.id)});});return found;}).slice(0,20);$('#search-results').innerHTML=results.length?results.map(r=>`<a href="${r.link}" data-action="search-result"><small>第${chinese(r.c.id)}讲 · ${r.c.title}</small><b>${r.title}</b><span>${r.desc}</span></a>`).join(''):'<div class="empty-state">暂时没有匹配的内容，换一个关键词试试。</div>';}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='shock')updateBond();if(t.id==='note-course'){$('#note-text').value=state.notes[t.value]||'';$('#note-status').textContent='输入后会自动保存到你的账号。';}if(t.id==='import-file'&&t.files[0]){try{const incoming=JSON.parse(await t.files[0].text());if(!validState(incoming))throw new Error('这不是有效的戊戌学习备份。');for(const c of courses){const r=incoming.courses[c.id];if(r&&(!Array.isArray(r.read)||!r.answers||typeof r.answers!=='object'||Array.isArray(r.answers)||!Number.isInteger(r.best)||r.best<0||r.best>c.quiz.length||!Number.isInteger(r.attempts)||r.attempts<0||typeof r.submitted!=='boolean'||!Number.isInteger(r.score)||r.score<0||r.score>c.quiz.length||!r.read.every(v=>c.sections.some(s=>s.id===v))||!Object.entries(r.answers).every(([key,v])=>c.quiz.some(q=>q.id===key&&Number.isInteger(v)&&v>=0&&v<q.options.length))))throw new Error('备份中的课程进度格式有误。');}if(!confirm('导入会替换当前浏览器中的学习进度、收藏和笔记。建议先导出当前备份。确定导入吗？'))return;state=incoming;save();render();toast('学习记录已导入。');}catch(err){toast(err.message||'无法读取备份文件。');}finally{t.value='';}}});
document.addEventListener('submit',async e=>{if(['bond-form','portfolio-form','simple-form'].includes(e.target.id)){e.preventDefault();return;}if(e.target.id!=='quiz-form')return;e.preventDefault();const c=courses.find(c=>c.id===+e.target.dataset.course),r=record(c.id);if(c.quiz.some(q=>!Number.isInteger(r.answers[q.id]))){toast('还有题目未作答，请完成全部题目后提交。');return;}const submitButton=e.target.querySelector('button[type=submit]');submitButton.disabled=true;try{const graded=await window.platform.submitQuiz(c,r.answers);Object.assign(record(c.id),graded);save();render();}catch(error){toast(error.message);submitButton.disabled=false;return;}$('.quiz-summary').scrollIntoView({behavior:'smooth',block:'center'});});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();$('#global-search').focus();}if(e.key==='Escape'&&mobileOpen){mobileOpen=false;$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('open');}});
render();

window.addEventListener('learning-remote-state',e=>{if(validState(e.detail)){state=e.detail;localStorage.setItem(KEY,JSON.stringify(state));}});
window.addEventListener('learning-sync',e=>{const el=document.querySelector('#cloud-sync-status');if(el){el.textContent=e.detail==='saving'?'保存中…':e.detail==='saved'?'进度已保存':'保存失败，请检查网络';el.dataset.status=e.detail;}});
function showAccount(){
  let d=document.createElement('dialog');d.className='account-dialog';d.innerHTML=`<form method="dialog"><div class="dialog-head"><b>账号设置</b><button class="icon-button" aria-label="关闭">${icon('close')}</button></div></form><div class="account-content"><p><b>${esc(window.platform.profile.display_name)}</b><br>${esc(window.platform.profile.email)}</p><p class="muted">当前浏览器：${esc(window.platform.device.label)}</p><form class="auth-form" id="password-change"><label>新密码<input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><label>再次输入新密码<input name="confirm" type="password" minlength="12" required autocomplete="new-password"></label><p class="auth-error" role="alert"></p><button class="button primary" type="submit">修改密码</button></form></div>`;document.body.appendChild(d);d.showModal();d.addEventListener('close',()=>d.remove());d.querySelector('#password-change').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(f.password.value!==f.confirm.value){f.querySelector('.auth-error').textContent='两次输入的密码不一致。';return;}const b=f.querySelector('button');b.disabled=true;try{await window.platform.changePassword(f.password.value);d.close();toast('密码已修改。');}catch(error){f.querySelector('.auth-error').textContent=error.message;b.disabled=false;}});
}

window.addEventListener('learning-server-metrics',e=>{for(const [id,r] of Object.entries(e.detail||{})){if(state.courses[id])for(const key of ['score','best','attempts','lastAnswers','courseRevision'])state.courses[id][key]=r[key];}localStorage.setItem(KEY,JSON.stringify(state));});
